raw_input.content:
const fs = require("fs");
const path = require("path");
const { JSDOM } = require("jsdom");

const html = fs.readFileSync(path.join(__dirname, "../..<local-workspace>"), "utf8").replace(/\/home\/ubuntu.*?opencode\/index\.html/,"");

const htmlPath = "<local-workspace>";
const htmlContent = fs.readFileSync(htmlPath, "utf8");

const dom = new JSDOM(htmlContent, { runScripts: "dangerously", pretendToBeVisual: true });
const { window } = dom;

window.addEventListener("DOMContentLoaded", () => {
  const lab = window.spreadPlateLab;
  let pass = true;
  function check(cond, msg) {
    console.log((cond ? "PASS" : "FAIL") + ": " + msg);
    if (!cond) pass = false;
  }
  try {
    check(!!lab, "window.spreadPlateLab exists");
    const s = lab.getState();
    check(s.step === "sterilize", "initial step = sterilize (got " + s.step + ")");
    check(s.completed === false, "initial completed = false");
    check(Array.isArray(s.history) && s.history.length === 0, "history empty");

    // out of order: cool before sterilize
    let r = lab.perform("cool");
    check(r.ok === false, "cool before sterilize -> ok:false");
    check(lab.getState().step === "sterilize", "step unchanged after invalid");

    // invalid action
    let r2 = lab.perform("bogus");
    check(r2.ok === false, "unknown action ok:false");

    // valid sequence
    check(lab.perform("sterilize").ok === true, "sterilize ok");
    check(lab.getState().step === "cool", "step advanced to cool");
    check(lab.perform("cool").ok === true, "cool ok");
    check(lab.getState().step === "sample", "step advanced to sample");
    check(lab.perform("sample").ok === true, "sample ok");
    check(lab.getState().step === "inoculate", "step advanced to inoculate");
    check(lab.perform("inoculate").ok === true, "inoculate ok");
    check(lab.getState().step === "spread", "step advanced to spread");
    check(lab.perform("spread").ok === true, "spread ok");
    check(lab.getState().step === "incubate", "step advanced to incubate");

    // incubate returns a promise
    const p = lab.perform("incubate");
    check(p && typeof p.then === "function", "incubate returns Promise");
    p.then(res => {
      check(res.ok === true, "incubate resolves ok:true");
      const fin = lab.getState();
      check(fin.step === "complete", "final step = complete");
      check(fin.completed === true, "completed = true");
      check(fin.history.length === 6, "history has 6 entries (got " + fin.history.length + ")");

      // reset
      lab.reset();
      const rs = lab.getState();
      check(rs.step === "sterilize", "reset -> step sterilize");
      check(rs.completed === false, "reset -> completed false");
      check(rs.history.length === 0, "reset -> history empty");

      // DOM markers
      const doc = window.document;
      ["lab-root","equipment-yeast-broth","equipment-cotton-plug","equipment-agar-plate","equipment-inoculation-loop","equipment-alcohol-lamp","equipment-clean-bench","step-instruction","feedback","progress"].forEach(m=>{
        check(!!doc.querySelector('[data-testid="'+m+'"]'), "marker "+m);
      });
      ["sterilize","cool","sample","inoculate","spread","incubate","reset"].forEach(a=>{
        check(!!doc.querySelector('[data-action="'+a+'"]'), "action "+a);
      });
      // draggable
      const dragCount = doc.querySelectorAll('[data-testid^="equipment-"][draggable="true"]').length;
      check(dragCount === 6, "6 equipment draggable markers (got " + dragCount + ")");
      // data-step on lab-root
      check(doc.querySelector('[data-testid="lab-root"]').getAttribute("data-step") === "sterilize", "data-step=sterilize after reset");

      console.log(pass ? "\nALL RUNTIME CHECKS PASS" : "\nSOME CHECKS FAILED");
      process.exit(pass ? 0 : 1);
    });
  } catch (e) {
    console.log("EXCEPTION:", e.message);
    process.exit(1);
  }
});
